package com.singtel.promotionservice;
import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.client.RestClient;import org.springframework.beans.factory.annotation.Value;import jakarta.validation.*;import jakarta.validation.constraints.*;import java.util.*;import java.time.Instant;import java.math.BigDecimal;import java.security.Principal;import com.fasterxml.jackson.databind.ObjectMapper;import com.singtel.platformcommon.*;
@RestController @RequestMapping("/api/v1/promotions")public class PromotionController{private final PromotionRepository repo;private final Events events;private final RestClient client;private final ObjectMapper json;private final String ruleUrl;public PromotionController(PromotionRepository r,Events e,RestClient c,ObjectMapper j,@Value("${platform.rule-url}")String u){repo=r;events=e;client=c;json=j;ruleUrl=u;}
 public record Create(@NotBlank @Pattern(regexp="[A-Z0-9_-]{3,30}")String code,@NotBlank @Size(min=3,max=120)String name,@NotBlank @Size(min=10,max=2000)String description,@Pattern(regexp="PERCENTAGE|FIXED|BENEFIT")@NotNull String discountType,@NotNull @DecimalMin("0.0001")BigDecimal discountValue,@Pattern(regexp="SGD")@NotNull String currency,@NotNull Instant startAt,@NotNull Instant endAt,@Positive long totalRedemptionLimit,@Positive int perCustomerLimit,@NotNull @DecimalMin("0.01")BigDecimal budgetLimit,@NotNull UUID ruleVersionId,@NotBlank String segment,@NotBlank String channel){}
 public record Transition(@PositiveOrZero long version){}
 private Map<String,Object> view(Promotion p){Map<String,Object> m=json.convertValue(p,new com.fasterxml.jackson.core.type.TypeReference<>(){});try{m.put("history",json.readValue(p.historyJson,List.class));m.remove("historyJson");return m;}catch(Exception e){throw new IllegalStateException(e);}}
 @GetMapping @PreAuthorize("hasAnyRole('MANAGER','APPROVER','ANALYST','ADMIN')")public List<Map<String,Object>> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size,@RequestParam(required=false)Lifecycle.Status status){if(page<0||size<1||size>100)throw new IllegalArgumentException();return repo.findAll(org.springframework.data.domain.PageRequest.of(page,size,org.springframework.data.domain.Sort.by("createdAt").descending())).stream().filter(p->status==null||p.status==status).map(this::view).toList();}
 @GetMapping("/{id}") @PreAuthorize("hasAnyRole('MANAGER','APPROVER','ANALYST','ADMIN')")public Map<String,Object> get(@PathVariable UUID id){return view(repo.findById(id).orElseThrow(DomainError::missing));}
 @PostMapping @ResponseStatus(org.springframework.http.HttpStatus.CREATED) @Transactional @PreAuthorize("hasAnyRole('MANAGER','ADMIN')")public Map<String,Object> create(@Valid @RequestBody Create c,Principal actor)throws Exception{if(!c.endAt().isAfter(c.startAt())||c.perCustomerLimit()>c.totalRedemptionLimit()||(c.discountType().equals("PERCENTAGE")&&c.discountValue().compareTo(new BigDecimal("100"))>0))throw DomainError.invalid("INVALID_TERMS","Invalid validity window or discount limits");client.get().uri(ruleUrl+"/api/v1/rules/"+c.ruleVersionId()).retrieve().toBodilessEntity();var p=json.convertValue(c,Promotion.class);p.id=UUID.randomUUID();p.createdBy=actor.getName();p.status=Lifecycle.Status.DRAFT;p.createdAt=Instant.now();p.updatedAt=p.createdAt;record(p,actor.getName());repo.save(p);events.append(p.id.toString(),"promotion.created",Map.of("promotionId",p.id,"version",p.version));return view(p);}
 @PostMapping("/{id}/{action:submit|approve|activate|pause|schedule|retire|expire|reject}") @Transactional @PreAuthorize("hasAnyRole('MANAGER','APPROVER','ADMIN')")public Map<String,Object> transition(@PathVariable UUID id,@PathVariable String action,@Valid @RequestBody Transition input,Principal actor,org.springframework.security.core.Authentication auth)throws Exception{var p=repo.findById(id).orElseThrow(DomainError::missing);if(p.version!=input.version())throw DomainError.conflict("STALE_VERSION","Refresh the campaign before updating it");boolean approval=action.equals("approve")||action.equals("reject");String required=approval?"ROLE_APPROVER":"ROLE_MANAGER";if(auth.getAuthorities().stream().noneMatch(a->a.getAuthority().equals(required)||a.getAuthority().equals("ROLE_ADMIN")))throw new org.springframework.security.access.AccessDeniedException("Role required");var next=switch(action){case "submit"->Lifecycle.Status.PENDING_APPROVAL;case "approve"->Lifecycle.Status.APPROVED;case "activate"->Lifecycle.Status.ACTIVE;case "pause"->Lifecycle.Status.PAUSED;case "schedule"->Lifecycle.Status.SCHEDULED;case "retire"->Lifecycle.Status.RETIRED;case "expire"->Lifecycle.Status.EXPIRED;case "reject"->Lifecycle.Status.DRAFT;default->throw new IllegalArgumentException();};Lifecycle.check(p.status,next,p.createdBy,actor.getName());Instant now=Instant.now();if(next==Lifecycle.Status.ACTIVE&&(now.isBefore(p.startAt)||!now.isBefore(p.endAt)))throw DomainError.invalid("OUTSIDE_VALIDITY","Campaign is outside its validity window");if(next==Lifecycle.Status.SCHEDULED&&!p.startAt.isAfter(now))throw DomainError.invalid("INVALID_SCHEDULE","Start must be in the future");if(next==Lifecycle.Status.EXPIRED&&now.isBefore(p.endAt))throw DomainError.invalid("NOT_EXPIRED","Campaign has not ended");p.status=next;p.updatedAt=now;if(next==Lifecycle.Status.APPROVED)p.approvedBy=actor.getName();record(p,actor.getName());repo.saveAndFlush(p);events.append(p.id.toString(),"promotion."+action,Map.of("promotionId",p.id,"status",p.status,"version",p.version));return view(p);}
 private void record(Promotion p,String actor)throws Exception{List<Object> h=new ArrayList<>(json.readValue(p.historyJson,List.class));h.add(Map.of("status",p.status,"at",p.updatedAt.toString(),"actor",actor));p.historyJson=json.writeValueAsString(h);}
}
